#!/bin/bash
set -e
D="$(cd "$(dirname "$0")" && pwd)"
APP="$D/NOVA Shell.app"
echo "Installing NOVA Shell into .app bundle..."
B64=''
if echo "$B64" | base64 -D > /dev/null 2>&1; then DECODE="-D"; else DECODE="-d"; fi
echo "$B64" | base64 $DECODE > "$APP/Contents/MacOS/novashell.py"
cat > "$APP/Contents/MacOS/novashell" << 'LAUNCHER'
#!/bin/bash
cd "$(dirname "$0")"
python3 novashell.py
LAUNCHER
chmod +x "$APP/Contents/MacOS/novashell"
if command -v python3 &>/dev/null; then echo "Ready. Double-click NOVA Shell.app to run."; else echo "Python 3 required: brew install python3"; fi